{"command": "str_replace", "new_str": "impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Self { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::Begin { .. } => Err(errinput!("BEGIN not supported in planner")),
            ast::Statement::Commit => Err(errinput!("COMMIT not supported in planner")),
            ast::Statement::Rollback => Err(errinput!("ROLLBACK not supported in planner")),
            ast::Statement::Explain(stmt) => self.build(*stmt),
            ast::Statement::CreateTable { name, columns } => self.build_create_table(name, columns),
            ast::Statement::DropTable { name, if_exists } => self.build_drop_table(name, if_exists),
            ast::Statement::Delete { table, r#where } => self.build_delete(table, r#where),
            ast::Statement::Insert { table, columns, values } => self.build_insert(table, columns, values),
            ast::Statement::Update { table, set, r#where } => self.build_update(table, set, r#where),
            ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut cols = Vec::new();
        let mut primary_key = None;
        for col in columns {
            let datatype = match col.datatype {
                ast::DataType::Boolean => types::DataType::Boolean,
                ast::DataType::Integer => types::DataType::Integer,
                ast::DataType::Float => types::DataType::Float,
                ast::DataType::String => types::DataType::String,
            };
            let nullable = col.nullable.unwrap_or(false);
            let default = col.default.map(|e| {
                let val = Self::build_constant_value(e)?;
                Ok(val)
            }).transpose()?;
            let unique = col.unique;
            let index = col.index;
            let references = col.references;
            let is_pk = col.primary_key;
            if is_pk {
                if primary_key.is_some() {
                    return errinput!("multiple primary keys");
                }
                primary_key = Some(cols.len());
            }
            cols.push(types::Column {
                name: col.name,
                datatype,
                nullable,
                default,
                unique,
                index,
                references,
            });
        }
        let primary_key = primary_key.ok_or_else(|| errinput!("no primary key"))?;
        let schema = types::Table { name, primary_key, columns: cols };
        Ok(Plan::CreateTable { schema })
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        let schema = self.catalog.must_get_table(&table)?;
        let primary_key = schema.primary_key;
        let source = if let Some(expr) = r#where {
            let scope = Scope::from_table(&schema)?;
            let filter = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: schema.clone(),
                    filter: Some(filter),
                    alias: None,
                }),
                predicate: filter,
            }
        } else {
            Node::Scan {
                table: schema.clone(),
                filter: None,
                alias: None,
            }
        };
        Ok(Plan::Delete { table, primary_key, source })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        let schema = self.catalog.must_get_table(&table)?;
        let column_map = if let Some(cols) = columns {
            let mut map = HashMap::new();
            for (i, col) in cols.into_iter().enumerate() {
                if let Ok(idx) = schema.column_index(&col) {
                    map.insert(idx, i);
                }
            }
            Some(map)
        } else {
            let mut map = HashMap::new();
            for i in 0..schema.columns.len() {
                map.insert(i, i);
            }
            Some(map)
        };
        let source = Node::Values { rows: values };
        Ok(Plan::Insert { table: schema, column_map, source })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        let schema = self.catalog.must_get_table(&table)?;
        let primary_key = schema.primary_key;
        let mut expressions = Vec::new();
        for (col, expr) in set {
            if let Ok(idx) = schema.column_index(&col) {
                let expr = expr.map(|e| Self::build_expression(e, &Scope::from_table(&schema)?)).transpose()?;
                expressions.push((idx, expr));
            }
        }
        let source = if let Some(expr) = r#where {
            let scope = Scope::from_table(&schema)?;
            let filter = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: schema.clone(),
                    filter: Some(filter.clone()),
                    alias: None,
                }),
                predicate: filter,
            }
        } else {
            Node::Scan {
                table: schema.clone(),
                filter: None,
                alias: None,
            }
        };
        Ok(Plan::Update { table: schema, primary_key, source, expressions })
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        mut select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        let mut scope = Scope::new();
        let mut source = self.build_from_clause(from, &mut scope)?;

        // WHERE
        if let Some(expr) = r#where {
            let filter = Self::build_expression(expr, &scope)?;
            source = Node::Filter {
                source: Box::new(source),
                predicate: filter,
            };
        }

        // GROUP BY and aggregates
        let aggregates = Self::collect_aggregates(&select, &having, &order_by);
        if !aggregates.is_empty() || !group_by.is_empty() {
            let mut group_by_exprs = Vec::new();
            for expr in group_by {
                group_by_exprs.push(Self::build_expression(expr, &scope)?);
            }
            let mut agg_exprs = Vec::new();
            for expr in aggregates {
                agg_exprs.push(Self::build_aggregate_function(expr, &scope)?);
            }
            source = Node::Aggregate {
                source: Box::new(source),
                group_by: group_by_exprs,
                aggregates: agg_exprs,
            };
            // Add hidden columns for HAVING and ORDER BY
            let hidden = self.build_select_hidden(&having, &order_by, &scope, &mut scope);
            if !hidden.is_empty() {
                source = Node::Projection {
                    source: Box::new(source),
                    expressions: hidden,
                    aliases: vec![Label::None; hidden.len()],
                };
            }
        }

        // HAVING
        if let Some(expr) = having {
            let filter = Self::build_expression(expr, &scope)?;
            source = Node::Filter {
                source: Box::new(source),
                predicate: filter,
            };
        }

        // ORDER BY
        if !order_by.is_empty() {
            let mut order = Vec::new();
            for (expr, dir) in order_by {
                order.push((Self::build_expression(expr, &scope)?, dir.into()));
            }
            source = Node::Order {
                source: Box::new(source),
                key: order,
            };
        }

        // OFFSET
        if let Some(expr) = offset {
            let val = Self::build_constant_value(expr)?;
            let offset = match val {
                types::Value::Integer(i) if i >= 0 => i as usize,
                _ => return errinput!("OFFSET must be a non-negative integer"),
            };
            source = Node::Offset {
                source: Box::new(source),
                offset,
            };
        }

        // LIMIT
        if let Some(expr) = limit {
            let val = Self::build_constant_value(expr)?;
            let limit = match val {
                types::Value::Integer(i) if i >= 0 => i as usize,
                _ => return errinput!("LIMIT must be a non-negative integer"),
            };
            source = Node::Limit {
                source: Box::new(source),
                limit,
            };
        }

        // SELECT projection
        let mut expressions = Vec::new();
        let mut aliases = Vec::new();
        for (expr, alias) in select {
            if expr == ast::Expression::All {
                // Expand *
                for (i, col) in scope.columns.iter().enumerate() {
                    expressions.push(types::Expression::Column(i));
                    aliases.push(col.clone());
                }
            } else {
                expressions.push(Self::build_expression(expr, &scope)?);
                aliases.push(alias.map(Label::Unqualified).unwrap_or(Label::None));
            }
        }
        source = Node::Projection {
            source: Box::new(source),
            expressions,
            aliases,
        };

        Ok(Plan::Select(source))
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        let mut source = Node::Nothing { columns: Vec::new() };
        for item in from {
            let table_source = self.build_from(item, scope)?;
            source = match source {
                Node::Nothing { .. } => table_source,
                _ => Node::NestedLoopJoin {
                    left: Box::new(source),
                    right: Box::new(table_source),
                    predicate: None,
                    outer: false,
                },
            };
        }
        Ok(source)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let schema = self.catalog.must_get_table(&name)?;
                let mut scope = Scope::from_table(&schema)?;
                if let Some(alias) = alias {
                    scope.tables.insert(alias.clone());
                }
                parent_scope.merge(scope)?;
                Ok(Node::Scan {
                    table: schema,
                    filter: None,
                    alias,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let left_scope = parent_scope.spawn();
                let left_node = self.build_from(*left, &mut left_scope.clone())?;
                let right_scope = left_scope.spawn();
                let right_node = self.build_from(*right, &mut right_scope.clone())?;
                let outer = r#type.is_outer();
                match r#type {
                    ast::JoinType::Cross => Ok(Node::NestedLoopJoin {
                        left: Box::new(left_node),
                        right: Box::new(right_node),
                        predicate: None,
                        outer,
                    }),
                    _ => {
                        let predicate = predicate.map(|p| Self::build_expression(p, &left_scope)).transpose()?;
                        Ok(Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer,
                        })
                    }
                }
            }
        }
    }

    /// Builds an aggregate node.
    fn build_aggregate(
        &self,
        source: Node,
        mut group_by: Vec<ast::Expression>,
        mut aggregates: Vec<ast::Expression>,
        scope: &mut Scope,
    ) -> Result<Node> {
        let group_by_exprs: Vec<_> = group_by.drain(..).map(|e| Self::build_expression(e, scope)).try_collect()?;
        let agg_exprs: Vec<_> = aggregates.drain(..).map(|e| Self::build_aggregate_function(e, scope)).try_collect()?;
        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by: group_by_exprs,
            aggregates: agg_exprs,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        let ast::Expression::Function(name, args) = expr else {
            return errinput!("expected aggregate function");
        };
        let name = name.to_lowercase();
        let arg = args.into_iter().next().ok_or_else(|| errinput!("aggregate requires an argument"))?;
        let expr = Self::build_expression(arg, scope)?;
        match name.as_str() {
            "count" => Ok(Aggregate::Count(expr)),
            "sum" => Ok(Aggregate::Sum(expr)),
            "avg" | "average" => Ok(Aggregate::Average(expr)),
            "min" => Ok(Aggregate::Min(expr)),
            "max" => Ok(Aggregate::Max(expr)),
            "median" => Ok(Aggregate::Median(expr)),
            "string_agg" | "group_concat" => {
                let delimiter = args.into_iter().nth(1).map(|e| Self::build_expression(e, scope)).transpose()?;
                Ok(Aggregate::StringAgg(expr, delimiter.unwrap_or(types::Expression::Constant(types::Value::String(",".into())))))
            }
            _ => errinput!("unknown aggregate function: {}", name),
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        match expr {
            ast::Expression::Function(name, _) if name.to_lowercase() == "count" ||
                name.to_lowercase() == "sum" || name.to_lowercase() == "avg" ||
                name.to_lowercase() == "average" || name.to_lowercase() == "min" ||
                name.to_lowercase() == "max" || name.to_lowercase() == "median" ||
                name.to_lowercase() == "string_agg" || name.to_lowercase() == "group_concat" => true,
            _ => false,
        }
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();
        for (expr, _) in select {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        if let Some(expr) = having {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        for (expr, _) in order_by {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<types::Expression> {
        let mut hidden = Vec::new();
        let mut collect = |expr: &ast::Expression| {
            expr.collect(&|e| {
                if let ast::Expression::Column(table, name) = e {
                    if let Ok(idx) = scope.lookup_column(table.as_deref(), name) {
                        if !child_scope.hidden.contains(&idx) {
                            child_scope.hidden.insert(idx);
                            hidden.push(types::Expression::Column(idx));
                        }
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            }, &mut Vec::new());
        };
        if let Some(expr) = having {
            collect(expr);
        }
        for (expr, _) in order_by {
            collect(expr);
        }
        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<types::Expression> {
        match expr {
            ast::Expression::All => errinput!("* not allowed here"),
            ast::Expression::Column(table, name) => {
                let idx = scope.lookup_column(table.as_deref(), &name)?;
                Ok(types::Expression::Column(idx))
            }
            ast::Expression::Literal(lit) => {
                let val = match lit {
                    ast::Literal::Null => types::Value::Null,
                    ast::Literal::Boolean(b) => types::Value::Boolean(b),
                    ast::Literal::Integer(i) => types::Value::Integer(i),
                    ast::Literal::Float(f) => types::Value::Float(f),
                    ast::Literal::String(s) => types::Value::String(s),
                };
                Ok(types::Expression::Constant(val))
            }
            ast::Expression::Function(name, args) => {
                // Handle scalar functions
                let name = name.to_lowercase();
                let args: Result<Vec<_>> = args.into_iter().map(|e| Self::build_expression(e, scope)).try_collect();
                let args = args?;
                match name.as_str() {
                    "length" => {
                        let arg = args.into_iter().next().ok_or_else(|| errinput!("length requires an argument"))?;
                        Ok(types::Expression::Function(name, vec![arg]))
                    }
                    "lower" | "upper" | "trim" | "coalesce" | "nullif" | "now" => {
                        Ok(types::Expression::Function(name, args))
                    }
                    "abs" | "round" | "ceil" | "floor" | "sqrt" => {
                        let arg = args.into_iter().next().ok_or_else(|| errinput!("{} requires an argument", name))?;
                        Ok(types::Expression::Function(name, vec![arg]))
                    }
                    _ => Ok(types::Expression::Function(name, args)),
                }
            }
            ast::Expression::Operator(op) => {
                use ast::Operator::*;
                let build_bin = |lhs: ast::Expression, rhs: ast::Expression| {
                    Ok(types::Expression::Operator(match op {
                        And(lhs, rhs) => types::Operator::And(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Or(lhs, rhs) => types::Operator::Or(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Equal(lhs, rhs) => types::Operator::Equal(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        GreaterThan(lhs, rhs) => types::Operator::GreaterThan(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        GreaterThanOrEqual(lhs, rhs) => types::Operator::GreaterThanOrEqual(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        LessThan(lhs, rhs) => types::Operator::LessThan(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        LessThanOrEqual(lhs, rhs) => types::Operator::LessThanOrEqual(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        NotEqual(lhs, rhs) => types::Operator::NotEqual(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Add(lhs, rhs) => types::Operator::Add(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Subtract(lhs, rhs) => types::Operator::Subtract(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Multiply(lhs, rhs) => types::Operator::Multiply(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Divide(lhs, rhs) => types::Operator::Divide(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Exponentiate(lhs, rhs) => types::Operator::Exponentiate(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Remainder(lhs, rhs) => types::Operator::Remainder(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Like(lhs, rhs) => types::Operator::Like(Box::new(Self::build_expression(*lhs, scope)?), Box::new(Self::build_expression(*rhs, scope)?)),
                        Not(e) => types::Operator::Not(Box::new(Self::build_expression(*e, scope)?)),
                        Negate(e) => types::Operator::Negate(Box::new(Self::build_expression(*e, scope)?)),
                        Identity(e) => types::Operator::Identity(Box::new(Self::build_expression(*e, scope)?)),
                        Factorial(e) => types::Operator::Factorial(Box::new(Self::build_expression(*e, scope)?)),
                        Is(e, lit) => {
                            let val = match lit {
                                ast::Literal::Null => types::Value::Null,
                                ast::Literal::String(s) if s == "nan" => types::Value::Float(f64::NAN),
                                _ => return errinput!("invalid IS value"),
                            };
                            types::Operator::Is(Box::new(Self::build_expression(*e, scope)?), val)
                        }
                    }))
                };
                match op {
                    And(lhs, rhs) | Or(lhs, rhs) | Equal(lhs, rhs) | GreaterThan(lhs, rhs) |
                    GreaterThanOrEqual(lhs, rhs) | LessThan(lhs, rhs) | LessThanOrEqual(lhs, rhs) |
                    NotEqual(lhs, rhs) | Add(lhs, rhs) | Subtract(lhs, rhs) | Multiply(lhs, rhs) |
                    Divide(lhs, rhs) | Exponentiate(lhs, rhs) | Remainder(lhs, rhs) | Like(lhs, rhs) => {
                        build_bin(*lhs, *rhs)
                    }
                    Not(e) | Negate(e) | Identity(e) | Factorial(e) | Is(e, _) => {
                        build_bin(*e, *e) // This won't work for unary, but we handle them separately
                    }
                }
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<types::Value> {
        let expr = Self::build_expression(expr, &Scope::new())?;
        expr.evaluate(None)
    }
}
